import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>المطورون غالبًا يحتاجون صورة كنص بدل ملف: أيقونة داخل ورقة أنماط أو شعار داخل بريد HTML أو صورة داخل JSON تحتاج الصورة محولة إلى نص.</p>\n<p>Base64 هو الترميز الذي يجعل ذلك ممكنًا: يحوّل بايتات صورة ثنائية إلى سلسلة نص بسيطة تستطيع العيش داخل كود وترميز ورسائل.</p>\n<p>يشرح هذا الدليل كيف يعمل <a href=\"/ar/tahwil-as-sura-ila-base64/\">محول صورة إلى Base64</a> من CompressMyPic، وما ينفع له كل صيغة إخراج، ومتى يكون تضمين صورة ذكيًا ومتى يكون خطأ.</p>\n<h2 id=\"what-is-base64\">ما Base64؟</h2>\n<p>Base64 طريقة لتمثيل بيانات ثنائية كنص: يأخذ بايتات ملف خامًا ويعيد كتابتها باستخدام 64 حرفًا آمنًا: حروف A إلى Z وa إلى z وأرقام 0 إلى 9 وعلامتي + و/.</p>\n<p>الحروف آمنة لأنها تظهر في كل أنظمة النص: بريد وملف JSON وورقة أنماط وقاعدة بيانات قد تحتوي سلسلة Base64 دون إفسادها، ما لا تستطيع بيانات ثنائية خام فعله. وBase64 ليس تشفيرًا ولا ضغطًا: أي شخص يستلم السلسلة يستطيع فك ترميزها مجددًا إلى الصورة الأصلية، والسلسلة دائمًا أطول من الملف الذي خرجت منه.</p>\n<p>فكر فيه كترجمة لا كتحويل: الصورة تبقى نفس الصورة؛ فقط تغيرت الأبجدية التي تُكتب بها.</p>\n<h2 id=\"how-encoding-works\">كيف يعمل ترميز Base64</h2>\n<p>يقرأ الترميز ملف الصورة ثلاثة بايتات معًا: كل مجموعة ثلاثة بايتات، 24 بت إجمالًا، تُقسم إلى أربع مجموعات ستة بت، وتتحول كل مجموعة ستة بت إلى حرف واحد.</p>\n<p>وعندما لا يكون طول الملف مضاعفًا لثلاثة، يضيف المشفر علامات يساوي كحشو: علامة يساوي واحدة تعني أن المجموعة الأخيرة كان لها بايتان، وعلامتان تعنيان أن لها بايتًا واحدًا. والنتيجة سلسلة نص تحتوي الصورة كلها: وفك الترميز يعكس العملية بدقة ويحوّل الحروف مجددًا إلى البايتات الأصلية دون أي فقدان.</p>\n<p>ويقوم المحول بكل هذا محليًا في متصفحك: تُقرأ الصورة وتُرمّز وتُعرض دون مغادرة جهازك أبدًا، فتبقى رسوم خاصة وأصول عملاء آمنة.</p>\n<h2 id=\"the-33-percent-overhead\">الزيادة 33 بالمئة</h2>\n<p>إخراج Base64 أكبر نحو 33 بالمئة من الملف الأصلي: صورة 90 KB تصبح سلسلة نحو 120 KB، لأن أربعة حروف نص تحمل فقط ثلاثة بايتات بيانات.</p>\n<p>الزيادة خاصية ثابتة للترميز لا عيب في الأداة: كل مشفر Base64 في أي لغة ينتج نفس زيادة الحجم لنفس الإدخال. وإخراجا HTML وCSS أكبر قليلًا بعد، لأنهما يضيفان غلافًا حول السلسلة: وسم الصورة يضيف ترميزًا، ودالة CSS تضيف صياغتها الخاصة، إضافة إلى السلسلة نفسها.</p>\n<p>هذه الزيادة هي أول ما يجب أن تفكر فيه قبل التضمين: أيقونة صغيرة تنمو من 3 KB إلى 4 KB، ما لا يلاحظه أحد، لكن صورة 2 MB تنمو إلى 2.7 MB، ما يلاحظه الجميع.</p>\n<h2 id=\"four-output-formats\">أربع صيغ إخراج في أداة واحدة</h2>\n<p>يوفر المحول أربع صيغ إخراج، كل منها مصمم لمهمة مختلفة: تختار التبويب الذي يناسب كودك، وتولّد الأداة المقتطف الدقيق الذي تحتاجه.</p>\n<p>تبويب \"رابط بيانات\" يعطيك URI البيانات الكاملة، جاهزة للصق في مصدر صورة أو ورقة أنماط: يشمل نوع الوسائط وعلامة الترميز وسلسلة Base64 في سلسلة واحدة. وتبويب \"Base64 خام\" يعطيك السلسلة وحدها، دون بادئة: تلك هي الصيغة التي تريدها رفعات API وقواعد البيانات عادة، لأن الكود المستلم يضيف سياقه الخاص.</p>\n<p>وتبويب صورة HTML يعطيك عنصر صورة كاملًا برابط البيانات كمصدر، زائد سمتي العرض والارتفاع مملوءتين تلقائيًا: وتبويب CSS يعطيك دالة url() جاهزة لخاصية خلفية.</p>\n<h2 id=\"data-url-explained\">روابط بيانات موضحة</h2>\n<p>رابط بيانات يبدأ بكلمة data، متبوعة بنوع الوسائط وعلامة الترميز وسلسلة Base64: رابط نموذجي يبدو هكذا: data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAA.</p>\n<p>المتصفحات تفهم روابط البيانات في أي مكان تعمل فيه رابط عادي: تستطيع استخدامها كمصدر صورة أو خلفية ورقة أنماط أو وجهة رابط، وسيعرضها المتصفح. والميزة هي الاكتفاء الذاتي: صفحة تستخدم روابط بيانات ليس لها ملفات صور منفصلة لجلبها، فتعمل دون اتصال وفي ملف واحد وفي سياقات حيث الطلبات الخارجية محظورة.</p>\n<p>والعيب هو الحجم: زيادة 33 بالمئة تنطبق على كل صورة مضمنة، وصفحة بروابط بيانات كثيرة تصبح ثقيلة وبطيئة المعالجة.</p>\n<h2 id=\"raw-base64-explained\">Base64 خام موضح</h2>\n<p>Base64 الخام هو السلسلة دون بادئة البيانات: إنه ما ترسله عندما يعرف المستلم نوع الصورة أصلًا، أو عندما يسافر النوع في حقل منفصل.</p>\n<p>رفعات API هي حالة الاستخدام الرئيسية: كائن JSON قد يحمل حقلًا يسمى image بالسلسلة الخام، زائد حقل يسمى mimeType بالصيغة، ويعيد الخادم بناء الملف. وقواعد البيانات تستخدم Base64 الخام بنفس الطريقة: حفظ صورة كنص في عمود نص يتجنب أنواع أعمدة ثنائية تتعامل معها بعض الأنظمة بشكل سيئ.</p>\n<p>وعندما تنسخ Base64 خامًا، احتفظ بالحشو: علامات يساوي في النهاية جزء من الترميز، وإزالتها قد تكسر مفككات تتوقع سلسلة كاملة.</p>\n<h2 id=\"html-img-snippet\">مقتطف صورة HTML</h2>\n<p>تبويب HTML يولّد عنصر صورة كاملًا برابط البيانات كمصدر: ويملأ أيضًا سمتي العرض والارتفاع تلقائيًا من أبعاد الصورة.</p>\n<p>تلك السمتان تهمّان أكثر مما تبدوان: بدونهما، لا يعرف المتصفح حجم الصورة حتى يفك ترميز السلسلة، ويتحرك تصميم الصفحة عندما تظهر الصورة أخيرًا. ومع العرض والارتفاع موجودين، يحجز المتصفح فورًا المقدار الصحيح من المساحة: يبقى التصميم مستقرًا، ما هو أفضل للقراء ولدرجات تغير التخطيط.</p>\n<p>والمقتطف جاهز للصق في أي ملف HTML: أضف سمة alt تصف الصورة قبل نشرها، لأن الأداة لا تستطيع معرفة ما تُظهره الصورة.</p>\n<h2 id=\"css-url-snippet\">مقتطف CSS url()</h2>\n<p>تبويب CSS يلف رابط البيانات في دالة url() وينتج قيمة تستطيع لصقها في خاصية background-image أو مشابهة: إنها أسرع طريقة لوضع صورة صغيرة في ورقة أنماط.</p>\n<p>صور CSS المضمنة شائعة لأيقونات وأنماط وخلفيات زخرفية: تُحمّل مع ورقة الأنماط، فلا طلب منفصل ولا وميض زخرفة مفقودة. والمقايضة هي وزن ورقة الأنماط: ورقة أنماط مليئة بصور مضمنة تنمو كثيرًا، والمتصفحات لا تستطيع حفظ الصور في ذاكرة تخزين مؤقت منفصلة عن CSS الذي يحملها.</p>\n<p>استخدم صيغة CSS لصور صغيرة ومستقرة نادرًا تتغير: شعار أو نمط متكرر مؤهل؛ ومعرض صور لا، لأن ورقة الأنماط ستصبح ضخمة.</p>\n<h2 id=\"quality-preservation\">الجودة: الترميز لا يغيّر شيئًا</h2>\n<p>ترميز صورة إلى Base64 لا يغيّر بكسلًا واحدًا: العملية قابلة للعكس تمامًا، وفك ترميز السلسلة يعيد البايتات الأصلية الدقيقة.</p>\n<p>GIF متحركة تحافظ على تحريكها، وملفات SVG تحافظ على كودها، وصور تحافظ على كل تفصيل: الترميز تمثيل مختلف لا صورة مختلفة. وهذا فرق مهم عن تحويل الصيغ: تغيير PNG إلى JPG يفقد بيانات، لكن ترميز PNG إلى Base64 لا يفقد شيئًا إطلاقًا.</p>\n<p>والشيء الوحيد الذي يتغير هو الحجم: السلسلة أكبر نحو ثلث من الملف، وتلك التكلفة هي ثمن حمل بيانات ثنائية كنص.</p>\n<h2 id=\"supported-formats\">أي صيغ وأحجام مدعومة</h2>\n<p>يقبل المحول ملفات PNG وJPG وWebP وGIF وSVG وBMP وICO، حتى 15 MB لكل ملف: ذلك يغطي شعارات وأيقونات وصورًا وصورًا متحركة في أداة واحدة.</p>\n<p>ملفات SVG تُرمّز دون مشكلة لأنها نص أصلًا: تقرأ الأداة كود SVG وتُرمّزه مثل أي ملف آخر، وتنتج سلسلة تُفك ترميزها مجددًا إلى نفس الرسم. وملفات ICO للأيقونات المفضلة تعمل أيضًا، ما ينفع عندما يحتاج موقع أيقونته مضمنة في صفحة ملف واحد أو قالب بريد: وICO المرمّز يُفك ترميزه مجددًا إلى نفس ملف الأيقونة.</p>\n<p>وللملفات القريبة من حد 15 MB، فكر في تصغير أولًا: PNG كبير مضغوط إلى JPG أصغر قبل الترميز ينتج سلسلة أقصر بكثير، وفقدان الجودة عند ذلك الحجم لا يُلاحظ غالبًا.</p>\n<h2 id=\"when-to-embed\">متى تضمّن صورة Base64</h2>\n<p>ضمّن صورًا صغيرة أساسية للصفحة: أيقونات وشعارات ورسوم زخرفية صغيرة أقل من بضعة كيلوبايت مثالية، لأن الزيادة لا تذكر.</p>\n<p>ضمّن صورًا في وثائق ملف واحد: بريد HTML أو تقرير مستقل أو صفحة دون اتصال لا تستطيع جلب ملفات خارجية، فالتضمين هو الطريقة الوحيدة لظهور الصورة. وضمّن صورًا في رفعات API وملفات إعدادات: عندما يجب أن تسافر الصورة داخل JSON أو داخل سجل قاعدة بيانات، فـBase64 هي الطريقة القياسية لحملها.</p>\n<p>وضمّن عندما نادرًا تتغير الصورة: شعار يبقى نفسه لسنوات لا يكلف شيئًا تضمينه، بينما صورة تُحدّث كل أسبوع تجبرك على تغيير الكود في كل مرة.</p>\n<h2 id=\"when-not-to-embed\">متى لا تضمّن</h2>\n<p>لا تضمّن صورًا كبيرة: صورة 2 MB تصبح سلسلة 2.7 MB داخل HTML، ويجب أن ينزّل المتصفح كل ذلك ويعالجه قبل أن تعرض الصفحة.</p>\n<p>لا تضمّن صورًا تظهر في صفحات كثيرة: شعار مضمن في كل صفحة يُنزّل في كل مرة، بينما شعار مرتبط يُحفظ في ذاكرة تخزين مؤقت مرة ويُعاد استخدامه في الموقع كله. ولا تضمّن صورًا في بريد دون مراجعة العميل: بعض عملاء البريد يحجبون صور Base64 المضمنة، وقد تصل رسالتك بصور مكسورة لتلك القراء.</p>\n<p>ولا تضمّن صورًا تحتاج فهرسة أو مشاركة: محرك بحث لا يستطيع اكتشاف صورة مضمنة بسهولة، وقارئ لا يستطيع النقر بزر الفأرة الأيمن وحفظها كما يستطيع مع ملف صورة عادي.</p>\n<h2 id=\"email-and-api-use\">Base64 في بريد وAPI</h2>\n<p>بريد HTML من أقدم استخدامات صور Base64: بريد رسالة واحدة، فصورة مضمنة تسافر معه وتُعرض حتى عندما يكون القارئ دون اتصال.</p>\n<p>ليست كل عملاء البريد متفقة مع ذلك: بعضها يحجب صور Base64 المضمنة لأسباب أمنية، فاختبر قالبك في العملاء التي يستخدمها جمهورك أولًا. وتستخدم واجهات API ترميز Base64 لسبب مختلف: JSON لا يستطيع حمل بيانات ثنائية: ونقطة نهاية رفع صور تقبل JSON تتوقع الصورة كسلسلة Base64، غالبًا مع نوع الوسائط في حقل منفصل.</p>\n<p>وعندما تبني تلك الرفعة، استخدم تبويب Base64 الخام: يعطيك السلسلة دون بادئة البيانات، وهي الصيغة التي تتوقعها معظم واجهات API.</p>\n<h2 id=\"privacy-local-processing\">خصوصية: الترميز يحدث في متصفحك</h2>\n<p>ترميز صورة عبر الإنترنت يعني رفعها إلى خادم، وهي فكرة سيئة لأيقونات مملوكة ورسوم سرية وأصول عملاء: هذه الأداة لا تفعل ذلك أبدًا.</p>\n<p>الملف يقرأه متصفحك ويُرمّز على جهازك وتُعرض السلسلة محليًا: لا نسخة من الصورة ولا من السلسلة تغادر حاسوبك. وهذا يعني أيضًا أن الأداة تعمل دون اتصال بمجرد تحميل الصفحة: تستطيع ترميز أيقونات في طائرة أو مكتب آمن دون أي وصول إلى الشبكة.</p>\n<p>وللفرق التي تتعامل مع مواد بصرية حساسة، الترميز المحلي هو الميزة الحاسمة: السلسلة التي تنسخها لك، ولا خادم يرى الصورة ولا شكلها المرمّز أبدًا.</p>\n<h2 id=\"how-to-use-the-tool\">كيف تستخدم أداة صورة إلى Base64</h2>\n<p>افتح <a href=\"/ar/tahwil-as-sura-ila-base64/\">محول صورة إلى Base64</a> وأسقط صورتك في منطقة الرفع، أو الصق لقطة مباشرة من الحافظة: تُقبل ملفات حتى 15 MB.</p>\n<p>اختر تبويب الإخراج الذي يناسب عملك: رابط بيانات لـURI كاملة، أو خام لرفعات API، أو HTML لعنصر صورة جاهز، أو CSS لخلفية ورقة أنماط.</p>\n<p>انسخ الإخراج بزر النسخ، أو نزّله كملف عندما تكون السلسلة طويلة ويشعر النسخ محفوفًا بالمخاطر: التنزيل يحفظ النص الدقيق، دون قص.</p>\n<p>للنسخة خطوة بخطوة، اقرأ <a href=\"/ar/blog/kayfiyya-tahwil-as-sura-ila-base64/\">كيف تحوّل صورة إلى Base64</a>، ولإطار القرار، راجع <a href=\"/ar/blog/suwar-base64-mata-tudamman/\">صور Base64: متى تضمّنها ومتى لا</a>. ولعكس العملية، استخدم <a href=\"/ar/tahwil-base64-ila-sura/\">مفكك ترميز Base64 إلى صورة</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"هل ترميز Base64 هو نفسه ضغط صورة؟","answer":"لا، إنه العكس من حيث الحجم: الضغط يجعل ملفًا أصغر، بينما Base64 يجعله أكبر نحو 33 بالمئة. ويغيّر الترميز التمثيل من ثنائي إلى نص دون تغيير أي بكسل، بينما الضغط يتخلص من بيانات."},{"question":"هل أستطيع تضمين صورة Base64 في وثيقة Word أو PDF؟","answer":"ليس مباشرة كسلسلة Base64: ملفات Word وPDF تحفظ الصور كبيانات ثنائية داخل الوثيقة، لا كنص Base64. وBase64 لكود ويب وبريد ورفعات JSON وصيغ أخرى قائمة على النص."},{"question":"لماذا سلسلة Base64 طويلة جدًا؟","answer":"لأنها تحمل الصورة كلها كنص، والنص وسيط أقل كفاءة من الثنائي: صورة 90 KB تصبح نحو 120 KB من حروف، وصورة 1 MB تصبح نحو 1.4 MB من نص. والطول هو ثمن حمل بيانات ثنائية كنص."},{"question":"هل يعمل ترميز Base64 لـGIF متحركة؟","answer":"نعم، الترميز لا يلمس بيانات البكسلات، فـGIF متحرك يُرمّز في سلسلة تُفك ترميزها مجددًا إلى نفس الملف المتحرك: والتحريك وعدد الإطارات والتوقيت تُحفظ كلها."},{"question":"ما أكبر صورة أستطيع تحويلها إلى Base64 هنا؟","answer":"تُقبل ملفات حتى 15 MB: الملفات الأكبر تنتج سلاسل طويلة جدًا غير مريحة للنسخ وبطيئة المعالجة في متصفح. وصغّر أو اضغط صورًا كبيرة قبل الترميز للحصول على سلسلة أقصر."},{"question":"هل تستطيع محركات البحث رؤية صور مضمنة كـBase64؟","answer":"معظمها لا: محرك بحث قد يفك ترميز رابط بيانات تقنيًا، لكن الصور المضمنة لا تُفهرس ولا تُصنّف ولا تُعرض في بحث الصور مثل ملفات الصور العادية. وإذا همت قابلية الاكتشاف، اربط الصورة كملف منفصل."}];
